// Explicit DEV selection of a checkpoint produced by the original source helper.
// Never remove defeated trainers or write false flags. No user storage or party edit.
export function selectCargoOfficerQACheckpoint(prepared){const old=prepared?.conditions?.S9_SHIP_ZONE1_COMPLETE_EVENT?.before;if(!old||prepared.evidence?.flagsWrittenByFixture!==0||prepared.evidence?.battleResultsWrittenByFixture!==0||old.progress?.currentStage!=='S9'||old.progress.completedEvents.includes('S9_SHIP_ZONE1_COMPLETE_EVENT')||['BLACKNET_BOMI_FINAL','BLACKNET_JUNSEOK_FINAL','BLACKNET_HWIGYEONG_FINAL'].some(id=>old.progress.defeatedTrainers.includes(id)))throw Error('ORIGINAL_BEFORE_ZONE1_CHECKPOINT_REQUIRED');return{...prepared,runtime:structuredClone(old),evidence:{...prepared.evidence,postBossFixture:false,officerCheckpoint:true,selectedCheckpoint:'original conditions.S9_SHIP_ZONE1_COMPLETE_EVENT.before',flagsWrittenBySelector:0,partyChangedBySelector:false,userSave:false}}}
